**Free

Dcl-S wSql Char(50) ;

Dcl-Ds wResult Qualified DIM(9999) ;
  wCol1 Char(10) ;
  wCol2 Char(10) ;
  wCol3 Char(10) ;
  wCol4 Char(10) ;
END-DS;

Dcl-S wCol1 Char(10) ;
Dcl-S wCol2 Char(10) ;
Dcl-S wCol3 Char(10) ;
Dcl-S wCol4 Char(10) ;

Dcl-S wCount Packed(7 : 0) Inz;
Dcl-S wTotalRecords Packed(4 : 0) Inz ;
Dcl-S wCurrentRecord Packed(4 : 0) Inz ;
Dcl-S wStartTime Char(8) ;
Dcl-S wEndTime Char(8) ;
Dcl-S wText Char(50) ;

wStartTime = %Char(%Time()) ;

wSql = 'Select * From PTESTTABL Order By TCOLUMN1' ;

Exec Sql Prepare wQuery from :wSql ;

Exec Sql Declare C1 Cursor for wQuery ;

Exec Sql Open C1 ;

Exec Sql Fetch Next From C1 For 9999 rows Into :wResult ;

Dow SqlErrd(3) > 0 ;

  wTotalRecords = SqlErrd(3) ;
  wCurrentRecord = 0 ;
  Dow wCurrentRecord < wTotalRecords ;
    wCount += 1 ;
    wCurrentRecord += 1 ;
  EndDo ;

  If SqlErrd(5) = 100 ;
    Leave ;
  EndIf;

  Exec Sql Fetch Next From C1 For 9999 rows Into :wResult ;
EndDo;

Exec Sql Close C1 ;

wEndTime = %Char(%Time()) ;
wText = 'Start: ' + wStartTime
      + ' End: ' + wEndTime
      + ' Records: ' + %Char(wCount) ;

Dsply wText ;

*InLr = *On ;

**Free

Dcl-F PPTESTFILE Keyed ;

Dcl-S wCount Packed(7 : 0) Inz ;
Dcl-S wStartTime Char(8) ;
Dcl-S wEndTime Char(8) ;
Dcl-S wText Char(50) ;

wStartTime = %Char(%Time()) ;

Setll *Start PPTESTFILE ;
Read PPTESTFILE ;
Dow Not %Eof(PPTESTFILE) ;
  wCount += 1 ;
  Read PPTESTFILE ;
EndDo;

wEndTime = %Char(%Time()) ;
wText = 'Start: ' + wStartTime
      + ' End: ' + wEndTime
      + ' Records: ' + %Char(wCount) ;

Dsply wText ;

*InLr = *On ;

**Free

Dcl-S wSql Char(50) ;

Dcl-S wCol1 Char(10) ;
Dcl-S wCol2 Char(10) ;
Dcl-S wCol3 Char(10) ;
Dcl-S wCol4 Char(10) ;

Dcl-S wCount Packed(7 : 0) Inz;
Dcl-S wStartTime Char(8) ;
Dcl-S wEndTime Char(8) ;
Dcl-S wText Char(50) ;

wStartTime = %Char(%Time()) ;

wSql = 'Select * From PTESTTABL Order By TCOLUMN1' ;

Exec Sql Prepare wQuery from :wSql ;

Exec Sql Declare C1 Cursor for wQuery ;

Exec Sql Open C1 ;

Exec Sql Fetch C1 Into :wCol1, :wCol2, :wCol3, :wCol4 ;

Dow SqlCod <> 100 ;
  wCount += 1 ;
  Exec Sql Fetch C1 Into :wCol1, :wCol2, :wCol3, :wCol4 ;
EndDo;

Exec Sql Close C1 ;

wEndTime = %Char(%Time()) ;
wText = 'Start: ' + wStartTime
      + ' End: ' + wEndTime
      + ' Records: ' + %Char(wCount) ;

Dsply wText ;

